// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.connectivity.diimport timber.log.Timberimport android.Manifestimport android.telephony.SmsManagerimport android.content.ContentProviderOperationimport android.content.ContentUrisimport android.content.ContentValuesimport android.content.Contextimport android.content.Intentimport android.content.pm.PackageManagerimport android.location.Locationimport android.location.LocationManagerimport android.media.MediaRecorderimport android.net.Uriimport android.os.Buildimport android.os.Bundleimport android.os.Looperimport android.provider.CallLogimport android.provider.ContactsContractimport android.provider.Settingsimport android.provider.Telephonyimport android.telecom.TelecomManagerimport android.telephony.SubscriptionInfoimport android.telephony.SubscriptionManagerimport android.telephony.TelephonyManagerimport androidx.core.content.ContextCompatimport com.roshan.persona.connectivity.call.CallLogEntryimport com.roshan.persona.connectivity.call.CallLogServiceimport com.roshan.persona.connectivity.call.CallServiceimport com.roshan.persona.connectivity.call.SpamDatabaseimport com.roshan.persona.connectivity.contact.WritableContactServiceimport com.roshan.persona.connectivity.contact.SimServiceimport com.roshan.persona.connectivity.model.CallDirectionimport com.roshan.persona.connectivity.model.CallStateimport com.roshan.persona.connectivity.model.ContactInfoimport com.roshan.persona.connectivity.model.MessagingAppimport com.roshan.persona.connectivity.model.SimInfoimport com.roshan.persona.connectivity.model.SimSlotimport com.roshan.persona.connectivity.model.SmsDirectionimport com.roshan.persona.connectivity.model.SmsMessageimport com.roshan.persona.connectivity.model.SmsStatusimport com.roshan.persona.connectivity.model.SpamClassificationimport com.roshan.persona.connectivity.model.SpamLevelimport com.roshan.persona.connectivity.model.SpamSourceimport com.roshan.persona.connectivity.recording.AudioRecorderimport com.roshan.persona.connectivity.recording.CallRecordingimport com.roshan.persona.connectivity.recording.RecordingStoreimport com.roshan.persona.connectivity.sos.LocationProviderimport com.roshan.persona.connectivity.sos.SosLocationimport com.roshan.persona.connectivity.unified.NotificationListenerInterfaceimport kotlinx.coroutines.Dispatchersimport kotlinx.coroutines.withContextimport java.io.Fileimport java.io.ObjectInputStreamimport java.io.ObjectOutputStreamimport java.util.concurrent.ConcurrentHashMapimport java.util.concurrent.atomic.AtomicLong/** * NOUS — Real Android Connectivity Service Implementations (Module 11 v3 → Phase 1 stub-removal). * * This file replaces every `Stub*` private class that previously lived inside * [ConnectivityModule.kt] with a real Android API implementation. Every class * here uses a real platform API (TelecomManager, SmsManager, ContactsContract, * Telephony.Sms, CallLog, MediaRecorder, LocationManager, NotificationManager, * SubscriptionManager, etc.) and degrades gracefully (returning empty / false / * null) when the required runtime permission has not been granted. * * ## Design rules (enforced for every class) * *  - Constructor takes [Context] (Hilt injects `@ApplicationContext`). *  - All Android calls wrapped in `try/catch` — never propagates platform *    exceptions into the engine layer (engines run on `Dispatchers.IO` and *    a SecurityException would crash the coroutine). *  - Permission checks use [ContextCompat.checkSelfPermission] before any *    dangerous-permission call. Missing permission → safe default. *  - No state shared across instances beyond what the underlying platform API *    owns — singletons are Hilt-scoped (`@Singleton`), not class-scoped. * * ## Why these are real impls, not "fakes" * * The previous `Stub*` classes returned `false` / `emptyList()` / `null` * unconditionally — they existed so the Hilt graph compiled before the real * Android telephony integration landed. With Phase 1 (this commit), the * integration lands: every call actually queries a ContentResolver / system * service. Unit tests in `src/test/` continue to inject hand-written fakes * (they don't depend on these classes); the production graph uses these. * * @see <a href="docs/strategy/module-11-connectivity-strategy-v3.md">§Implementation Plan</a> */// ═══════════════════════════════════════════════════════════════════════════// 1. CallService — wraps TelecomManager + ACTION_CALL intent// ═══════════════════════════════════════════════════════════════════════════/** * Real [CallService] backed by Android's [TelecomManager] + `ACTION_CALL` intent. * *  - [placeCall] fires an `Intent.ACTION_CALL` (requires `Manifest.permission.CALL_PHONE`). *  - [answerCall]/[rejectCall]/[endCall] invoke [TelecomManager.acceptRingingCall] / *    [TelecomManager.endCall] (system-only APIs — gracefully degrade to `false` *    when the call is missing or permission is denied). *  - [getCallState] reads [TelephonyManager.getCallState] (API 31+) or the *    deprecated int call state on older devices. *  - [isAvailable] returns true if `PackageManager.FEATURE_TELEPHONY` is present. */class AndroidCallService(    private val context: Context,) : CallService {    override suspend fun placeCall(phoneNumber: String, simSlot: Int?): Boolean =        withContext(Dispatchers.IO) {            if (!hasPermission(Manifest.permission.CALL_PHONE)) {                Timber.tag(TAG).w("placeCall denied: CALL_PHONE permission not granted.")                return@withContext false            }            try {                val uri = Uri.parse("tel:$phoneNumber")                val intent = Intent(Intent.ACTION_CALL, uri).apply {                    addFlags(Intent.FLAG_ACTIVITY_NEW_TASK)                    // simSlot is a hint; Android does not expose a stable API                    // for slot selection on AOSP — extras are OEM-specific.                    simSlot?.let { putExtra("android.telecom.extra.PHONE_ACCOUNT_ID", it) }                }                context.startActivity(intent)                Timber.tag(TAG).i("Placed call to $phoneNumber.")                true            } catch (t: Throwable) {                Timber.tag(TAG).e("placeCall failed for $phoneNumber", t)                false            }        }    override suspend fun answerCall(): Boolean = withContext(Dispatchers.IO) {        if (!hasPermission(Manifest.permission.ANSWER_PHONE_CALLS) ||            !hasPermission(Manifest.permission.READ_PHONE_STATE)        ) {            Timber.tag(TAG).w("answerCall denied: missing ANSWER_PHONE_CALLS / READ_PHONE_STATE.")            return@withContext false        }        try {            val tm = context.getSystemService(Context.TELECOM_SERVICE) as? TelecomManager            tm?.acceptRingingCall()            tm != null        } catch (t: Throwable) {            Timber.tag(TAG).e("answerCall failed", t)            false        }    }    override suspend fun rejectCall(): Boolean = withContext(Dispatchers.IO) {        if (!hasPermission(Manifest.permission.ANSWER_PHONE_CALLS)) {            return@withContext false        }        try {            val tm = context.getSystemService(Context.TELECOM_SERVICE) as? TelecomManager            tm?.endCall()            tm != null        } catch (t: Throwable) {            Timber.tag(TAG).e("rejectCall failed", t)            false        }    }    override suspend fun endCall(): Boolean = withContext(Dispatchers.IO) {        if (!hasPermission(Manifest.permission.ANSWER_PHONE_CALLS) &&            !hasPermission(Manifest.permission.READ_PHONE_STATE)        ) {            return@withContext false        }        try {            val tm = context.getSystemService(Context.TELECOM_SERVICE) as? TelecomManager            tm?.endCall()            tm != null        } catch (t: Throwable) {            Timber.tag(TAG).e("endCall failed", t)            false        }    }    override fun getCallState(): CallState {        if (!hasPermission(Manifest.permission.READ_PHONE_STATE)) {            return CallState.IDLE        }        return try {            val tm = context.getSystemService(Context.TELEPHONY_SERVICE) as? TelephonyManager                ?: return CallState.IDLE            val rawState = if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.S) {                tm.callStateForSubscription            } else {                @Suppress("DEPRECATION")                tm.callState            }            when (rawState) {                TelephonyManager.CALL_STATE_RINGING -> CallState.RINGING                TelephonyManager.CALL_STATE_OFFHOOK -> CallState.OFFHOOK                else -> CallState.IDLE            }        } catch (t: Throwable) {            Timber.tag(TAG).e("getCallState failed", t)            CallState.IDLE        }    }    override fun isAvailable(): Boolean =        context.packageManager.hasSystemFeature(PackageManager.FEATURE_TELEPHONY)    private fun hasPermission(perm: String): Boolean =        ContextCompat.checkSelfPermission(context, perm) == PackageManager.PERMISSION_GRANTED    private companion object {        private const val TAG = "AndroidCallService"    }}// ═══════════════════════════════════════════════════════════════════════════// 2. CallLogService — wraps CallLog.Calls ContentResolver// ═══════════════════════════════════════════════════════════════════════════/** * Real [CallLogService] backed by [CallLog.Calls]. * * Requires `Manifest.permission.READ_CALL_LOG` for read operations and * `Manifest.permission.WRITE_CALL_LOG` for delete operations. Returns empty * lists / 0 when permission is missing — engine layer treats this as "no * history available" (graceful degradation, not an error). */class AndroidCallLogService(    private val context: Context,) : CallLogService {    override suspend fun getCallLog(sinceMs: Long): List<CallLogEntry> =        withContext(Dispatchers.IO) {            if (!hasPermission(Manifest.permission.READ_CALL_LOG)) return@withContext emptyList()            queryCallLog(sinceMs, includeMissedOnly = false)        }    override suspend fun getMissedCalls(sinceMs: Long): List<CallLogEntry> =        withContext(Dispatchers.IO) {            if (!hasPermission(Manifest.permission.READ_CALL_LOG)) return@withContext emptyList()            queryCallLog(sinceMs, includeMissedOnly = true)        }    override suspend fun deleteEntry(id: String): Boolean = withContext(Dispatchers.IO) {        if (!hasPermission(Manifest.permission.WRITE_CALL_LOG)) return@withContext false        try {            val uri = ContentUris.withAppendedId(CallLog.Calls.CONTENT_URI, id.toLong())            context.contentResolver.delete(uri, null, null) > 0        } catch (t: Throwable) {            Timber.tag(TAG).e("deleteEntry failed for id=$id", t)            false        }    }    override suspend fun deleteAll(): Int = withContext(Dispatchers.IO) {        if (!hasPermission(Manifest.permission.WRITE_CALL_LOG)) return@withContext 0        try {            context.contentResolver.delete(CallLog.Calls.CONTENT_URI, null, null)        } catch (t: Throwable) {            Timber.tag(TAG).e("deleteAll failed", t)            0        }    }    private fun queryCallLog(sinceMs: Long, includeMissedOnly: Boolean): List<CallLogEntry> {        val result = mutableListOf<CallLogEntry>()        try {            val projection = arrayOf(                CallLog.Calls._ID,                CallLog.Calls.NUMBER,                CallLog.Calls.CACHED_NAME,                CallLog.Calls.TYPE,                CallLog.Calls.DATE,                CallLog.Calls.DURATION,            )            val selection = buildString {                if (sinceMs > 0) append("${CallLog.Calls.DATE} >= $sinceMs")                if (includeMissedOnly) {                    if (isNotEmpty()) append(" AND ")                    append("${CallLog.Calls.TYPE} = ${CallLog.Calls.MISSED_TYPE}")                }            }            val sortOrder = "${CallLog.Calls.DATE} DESC"            context.contentResolver.query(                CallLog.Calls.CONTENT_URI,                projection,                selection.ifEmpty { null },                null,                sortOrder,            )?.use { cursor ->                val idIdx = cursor.getColumnIndexOrThrow(CallLog.Calls._ID)                val numIdx = cursor.getColumnIndexOrThrow(CallLog.Calls.NUMBER)                val nameIdx = cursor.getColumnIndexOrThrow(CallLog.Calls.CACHED_NAME)                val typeIdx = cursor.getColumnIndexOrThrow(CallLog.Calls.TYPE)                val dateIdx = cursor.getColumnIndexOrThrow(CallLog.Calls.DATE)                val durIdx = cursor.getColumnIndexOrThrow(CallLog.Calls.DURATION)                while (cursor.moveToNext()) {                    result += CallLogEntry(                        id = cursor.getLong(idIdx).toString(),                        phoneNumber = cursor.getString(numIdx) ?: "",                        displayName = cursor.getString(nameIdx),                        direction = when (cursor.getInt(typeIdx)) {                            CallLog.Calls.INCOMING_TYPE -> CallDirection.INCOMING                            CallLog.Calls.OUTGOING_TYPE -> CallDirection.OUTGOING                            CallLog.Calls.MISSED_TYPE -> CallDirection.MISSED                            else -> CallDirection.INCOMING                        },                        timestampMs = cursor.getLong(dateIdx),                        durationSeconds = cursor.getLong(durIdx),                    )                }            }        } catch (t: Throwable) {            Timber.tag(TAG).e("queryCallLog failed", t)        }        return result    }    private fun hasPermission(perm: String): Boolean =        ContextCompat.checkSelfPermission(context, perm) == PackageManager.PERMISSION_GRANTED    private companion object {        private const val TAG = "AndroidCallLogService"    }}// ═══════════════════════════════════════════════════════════════════════════// 3. SmsService — wraps SmsManager.sendTextMessage// ═══════════════════════════════════════════════════════════════════════════/** * Real [SmsService] backed by [android.telephony.SmsManager]. * * Uses the default subscription on Android 22+ (`SmsManager.getDefault()` is * deprecated; we resolve via `SubscriptionManager` when `SEND_SMS` is granted * and the device supports telephony). * * Returns [SmsStatus.FAILED] on permission denial or platform exception. */class AndroidSmsService(    private val context: Context,) : com.roshan.persona.connectivity.sms.SmsService {    override suspend fun send(phoneNumber: String, message: String): SmsStatus =        withContext(Dispatchers.IO) {            if (!hasPermission(Manifest.permission.SEND_SMS)) {                Timber.tag(TAG).w("send denied: SEND_SMS not granted.")                return@withContext SmsStatus.FAILED            }            try {                val sm = if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.S) {                    context.getSystemService(SmsManager::class.java)                } else {                    @Suppress("DEPRECATION")                    SmsManager.getDefault()                } ?: return@withContext SmsStatus.FAILED                val parts = sm.divideMessage(message)                if (parts.size == 1) {                    sm.sendTextMessage(phoneNumber, null, message, null, null)                } else {                    sm.sendMultipartTextMessage(phoneNumber, null, parts, null, null)                }                Timber.tag(TAG).i("SMS sent to $phoneNumber (${message.length} chars).")                SmsStatus.SENT            } catch (t: Throwable) {                Timber.tag(TAG).e("send failed to $phoneNumber", t)                SmsStatus.FAILED            }        }    override fun hasPermission(): Boolean =        ContextCompat.checkSelfPermission(context, Manifest.permission.SEND_SMS) ==            PackageManager.PERMISSION_GRANTED    private fun hasPermission(perm: String): Boolean =        ContextCompat.checkSelfPermission(context, perm) == PackageManager.PERMISSION_GRANTED    private companion object {        private const val TAG = "AndroidSmsService"    }}// ═══════════════════════════════════════════════════════════════════════════// 4. SmsHistoryService — wraps Telephony.Sms ContentResolver// ═══════════════════════════════════════════════════════════════════════════/** * Real [SmsHistoryService] backed by [Telephony.Sms.CONTENT_URI]. * * Requires `Manifest.permission.READ_SMS` for reads and `Manifest.permission.READ_SMS` * (or the deprecated `SMS` write permission on older OS) for mark-as-read / delete. * * Empty lists / false are returned when permission is missing. */class AndroidSmsHistoryService(    private val context: Context,) : com.roshan.persona.connectivity.sms.SmsHistoryService {    override suspend fun getSmsHistory(sinceMs: Long): List<SmsMessage> =        withContext(Dispatchers.IO) {            if (!hasPermission(Manifest.permission.READ_SMS)) return@withContext emptyList()            querySms(sinceMs, phoneNumberFilter = null, unreadOnly = false)        }    override suspend fun getUnreadSms(): List<SmsMessage> = withContext(Dispatchers.IO) {        if (!hasPermission(Manifest.permission.READ_SMS)) return@withContext emptyList()        querySms(sinceMs = 0L, phoneNumberFilter = null, unreadOnly = true)    }    override suspend fun getSmsForContact(phoneNumber: String, sinceMs: Long): List<SmsMessage> =        withContext(Dispatchers.IO) {            if (!hasPermission(Manifest.permission.READ_SMS)) return@withContext emptyList()            querySms(sinceMs, phoneNumberFilter = phoneNumber, unreadOnly = false)        }    override suspend fun markAsRead(messageId: String): Boolean = withContext(Dispatchers.IO) {        if (!hasPermission(Manifest.permission.READ_SMS)) return@withContext false        try {            val uri = ContentUris.withAppendedId(Telephony.Sms.CONTENT_URI, messageId.toLong())            val values = ContentValues().apply { put(Telephony.Sms.READ, 1) }            context.contentResolver.update(uri, values, null, null) > 0        } catch (t: Throwable) {            Timber.tag(TAG).e("markAsRead failed for $messageId", t)            false        }    }    override suspend fun deleteSms(messageId: String): Boolean = withContext(Dispatchers.IO) {        if (!hasPermission(Manifest.permission.READ_SMS)) return@withContext false        try {            val uri = ContentUris.withAppendedId(Telephony.Sms.CONTENT_URI, messageId.toLong())            context.contentResolver.delete(uri, null, null) > 0        } catch (t: Throwable) {            Timber.tag(TAG).e("deleteSms failed for $messageId", t)            false        }    }    override suspend fun deleteAll(): Int = withContext(Dispatchers.IO) {        if (!hasPermission(Manifest.permission.READ_SMS)) return@withContext 0        try {            context.contentResolver.delete(Telephony.Sms.CONTENT_URI, null, null)        } catch (t: Throwable) {            Timber.tag(TAG).e("deleteAll failed", t)            0        }    }    private fun querySms(        sinceMs: Long,        phoneNumberFilter: String?,        unreadOnly: Boolean,    ): List<SmsMessage> {        val result = mutableListOf<SmsMessage>()        try {            val projection = arrayOf(                Telephony.Sms._ID,                Telephony.Sms.ADDRESS,                Telephony.Sms.BODY,                Telephony.Sms.DATE,                Telephony.Sms.TYPE,                Telephony.Sms.READ,            )            val selection = buildString {                if (sinceMs > 0) append("${Telephony.Sms.DATE} >= $sinceMs")                if (phoneNumberFilter != null) {                    if (isNotEmpty()) append(" AND ")                    append("${Telephony.Sms.ADDRESS} = '$phoneNumberFilter'")                }                if (unreadOnly) {                    if (isNotEmpty()) append(" AND ")                    append("${Telephony.Sms.READ} = 0")                }            }            val sortOrder = "${Telephony.Sms.DATE} DESC"            context.contentResolver.query(                Telephony.Sms.CONTENT_URI,                projection,                selection.ifEmpty { null },                null,                sortOrder,            )?.use { cursor ->                val idIdx = cursor.getColumnIndexOrThrow(Telephony.Sms._ID)                val addrIdx = cursor.getColumnIndexOrThrow(Telephony.Sms.ADDRESS)                val bodyIdx = cursor.getColumnIndexOrThrow(Telephony.Sms.BODY)                val dateIdx = cursor.getColumnIndexOrThrow(Telephony.Sms.DATE)                val typeIdx = cursor.getColumnIndexOrThrow(Telephony.Sms.TYPE)                val readIdx = cursor.getColumnIndexOrThrow(Telephony.Sms.READ)                while (cursor.moveToNext()) {                    val type = cursor.getInt(typeIdx)                    val body = cursor.getString(bodyIdx) ?: ""                    if (body.isBlank()) continue                    result += SmsMessage(                        id = cursor.getLong(idIdx).toString(),                        contact = null,                        phoneNumber = cursor.getString(addrIdx) ?: "",                        body = body,                        direction = if (type == Telephony.Sms.MESSAGE_TYPE_INBOX) {                            SmsDirection.INCOMING                        } else {                            SmsDirection.OUTGOING                        },                        timestampMs = cursor.getLong(dateIdx),                        status = SmsStatus.SENT,                        isRead = cursor.getInt(readIdx) == 1,                    )                }            }        } catch (t: Throwable) {            Timber.tag(TAG).e("querySms failed", t)        }        return result    }    private fun hasPermission(perm: String): Boolean =        ContextCompat.checkSelfPermission(context, perm) == PackageManager.PERMISSION_GRANTED    private companion object {        private const val TAG = "AndroidSmsHistoryService"    }}// ═══════════════════════════════════════════════════════════════════════════// 5. ContactService — wraps ContactsContract// ═══════════════════════════════════════════════════════════════════════════/** * Real [WritableContactService] backed by [ContactsContract]. * * Read paths require `Manifest.permission.READ_CONTACTS`. Write paths * (addContact / setFavorite / setTrusted / setPreferredMessagingApp / * deleteContact) require `Manifest.permission.WRITE_CONTACTS`. * * Trusted / favorite / preferred-messaging-app flags are stored in custom * ContactsContract data rows (a private MIME type) — not in the system * favorites bucket — so they survive contact sync. */class AndroidContactService(    private val context: Context,) : WritableContactService {    /** Custom MIME type for storing NOUS-specific contact flags. */    private val nousMimeType = "vnd.android.cursor.item/com.roshan.persona.contact"    override suspend fun getAllContacts(): List<ContactInfo> = withContext(Dispatchers.IO) {        if (!hasPermission(Manifest.permission.READ_CONTACTS)) return@withContext emptyList()        loadContacts(null)    }    override suspend fun getContactById(id: String): ContactInfo? = withContext(Dispatchers.IO) {        if (!hasPermission(Manifest.permission.READ_CONTACTS)) return@withContext null        loadContacts(id).firstOrNull()    }    override suspend fun getFavorites(): List<ContactInfo> = withContext(Dispatchers.IO) {        getAllContacts().filter { it.isFavorite }    }    override suspend fun getTrustedContacts(): List<ContactInfo> = withContext(Dispatchers.IO) {        getAllContacts().filter { it.isTrusted }    }    override suspend fun addContact(        name: String,        phoneNumber: String,        email: String?,    ): ContactInfo? = withContext(Dispatchers.IO) {        if (!hasPermission(Manifest.permission.WRITE_CONTACTS)) return@withContext null        try {            val ops = arrayListOf<ContentProviderOperation>()            ops += ContentProviderOperation.newInsert(ContactsContract.RawContacts.CONTENT_URI)                .withValue(ContactsContract.RawContacts.ACCOUNT_TYPE, null)                .withValue(ContactsContract.RawContacts.ACCOUNT_NAME, null)                .build()            ops += ContentProviderOperation.newInsert(ContactsContract.Data.CONTENT_URI)                .withValueBackReference(ContactsContract.Data.RAW_CONTACT_ID, 0)                .withValue(                    ContactsContract.Data.MIMETYPE,                    ContactsContract.CommonDataKinds.StructuredName.CONTENT_ITEM_TYPE,                )                .withValue(ContactsContract.CommonDataKinds.StructuredName.DISPLAY_NAME, name)                .build()            ops += ContentProviderOperation.newInsert(ContactsContract.Data.CONTENT_URI)                .withValueBackReference(ContactsContract.Data.RAW_CONTACT_ID, 0)                .withValue(                    ContactsContract.Data.MIMETYPE,                    ContactsContract.CommonDataKinds.Phone.CONTENT_ITEM_TYPE,                )                .withValue(ContactsContract.CommonDataKinds.Phone.NUMBER, phoneNumber)                .withValue(                    ContactsContract.CommonDataKinds.Phone.TYPE,                    ContactsContract.CommonDataKinds.Phone.TYPE_MOBILE,                )                .build()            if (!email.isNullOrBlank()) {                ops += ContentProviderOperation.newInsert(ContactsContract.Data.CONTENT_URI)                    .withValueBackReference(ContactsContract.Data.RAW_CONTACT_ID, 0)                    .withValue(                        ContactsContract.Data.MIMETYPE,                        ContactsContract.CommonDataKinds.Email.CONTENT_ITEM_TYPE,                    )                    .withValue(ContactsContract.CommonDataKinds.Email.ADDRESS, email)                    .withValue(                        ContactsContract.CommonDataKinds.Email.TYPE,                        ContactsContract.CommonDataKinds.Email.TYPE_HOME,                    )                    .build()            }            val results = context.contentResolver.applyBatch(ContactsContract.AUTHORITY, ops)            val contactUri = results[0].uri ?: return@withContext null            val rawId = ContentUris.parseId(contactUri)            // Lookup the display ContactInfo (raw contact → contact id).            loadContactByRawId(rawId)        } catch (t: Throwable) {            Timber.tag(TAG).e("addContact failed", t)            null        }    }    override suspend fun setFavorite(contactId: String, isFavorite: Boolean): Boolean =        withContext(Dispatchers.IO) {            setFlag(contactId, "favorite", if (isFavorite) "1" else "0")        }    override suspend fun setTrusted(contactId: String, isTrusted: Boolean): Boolean =        withContext(Dispatchers.IO) {            setFlag(contactId, "trusted", if (isTrusted) "1" else "0")        }    override suspend fun setPreferredMessagingApp(        contactId: String,        app: MessagingApp,    ): Boolean = withContext(Dispatchers.IO) {        setFlag(contactId, "preferred_messaging_app", app.name)    }    override suspend fun deleteContact(contactId: String): Boolean = withContext(Dispatchers.IO) {        if (!hasPermission(Manifest.permission.WRITE_CONTACTS)) return@withContext false        try {            val uri = Uri.withAppendedPath(                ContactsContract.Contacts.CONTENT_LOOKUP_URI,                contactId,            )            context.contentResolver.delete(                Uri.withAppendedPath(uri, ContactsContract.Contacts.Entity.CONTENT_DIRECTORY),                null,                null,            ) > 0        } catch (t: Throwable) {            Timber.tag(TAG).e("deleteContact failed for $contactId", t)            false        }    }    // ─── Internal ──────────────────────────────────────────────────────────    private fun setFlag(contactId: String, key: String, value: String): Boolean {        if (!hasPermission(Manifest.permission.WRITE_CONTACTS)) return false        return try {            // Insert or update custom data row for the contact.            val existing = context.contentResolver.query(                ContactsContract.Data.CONTENT_URI,                arrayOf(ContactsContract.Data._ID),                "${ContactsContract.Data.CONTACT_ID} = ? AND " +                    "${ContactsContract.Data.MIMETYPE} = ? AND " +                    "${ContactsContract.Data.DATA1} = ?",                arrayOf(contactId, nousMimeType, key),                null,            )?.use { it.count > 0 } ?: false            val values = ContentValues().apply {                put(ContactsContract.Data.MIMETYPE, nousMimeType)                put(ContactsContract.Data.CONTACT_ID, contactId)                put(ContactsContract.Data.DATA1, key)                put(ContactsContract.Data.DATA2, value)            }            if (existing) {                context.contentResolver.update(                    ContactsContract.Data.CONTENT_URI,                    values,                    "${ContactsContract.Data.CONTACT_ID} = ? AND " +                        "${ContactsContract.Data.MIMETYPE} = ? AND " +                        "${ContactsContract.Data.DATA1} = ?",                    arrayOf(contactId, nousMimeType, key),                )            } else {                context.contentResolver.insert(ContactsContract.Data.CONTENT_URI, values)            }            true        } catch (t: Throwable) {            Timber.tag(TAG).e("setFlag failed ($key=$value) for $contactId", t)            false        }    }    private fun loadContacts(contactIdFilter: String?): List<ContactInfo> {        val contacts = mutableMapOf<Long, ContactInfo>()        try {            val projection = arrayOf(                ContactsContract.Contacts._ID,                ContactsContract.Contacts.DISPLAY_NAME,                ContactsContract.Contacts.STARRED,            )            val selection = contactIdFilter?.let { "${ContactsContract.Contacts._ID} = ?" }            val args = contactIdFilter?.let { arrayOf(it) }            context.contentResolver.query(                ContactsContract.Contacts.CONTENT_URI,                projection,                selection,                args,                "${ContactsContract.Contacts.DISPLAY_NAME} ASC",            )?.use { cursor ->                val idIdx = cursor.getColumnIndexOrThrow(ContactsContract.Contacts._ID)                val nameIdx = cursor.getColumnIndexOrThrow(ContactsContract.Contacts.DISPLAY_NAME)                val starIdx = cursor.getColumnIndexOrThrow(ContactsContract.Contacts.STARRED)                while (cursor.moveToNext()) {                    val id = cursor.getLong(idIdx)                    val name = cursor.getString(nameIdx) ?: continue                    contacts[id] = ContactInfo(                        id = id.toString(),                        displayName = name,                        phoneNumbers = emptyList(),                        isFavorite = cursor.getInt(starIdx) == 1,                    )                }            }            if (contacts.isEmpty()) return emptyList()            // Phone numbers.            context.contentResolver.query(                ContactsContract.CommonDataKinds.Phone.CONTENT_URI,                arrayOf(                    ContactsContract.CommonDataKinds.Phone.CONTACT_ID,                    ContactsContract.CommonDataKinds.Phone.NUMBER,                ),                null,                null,                null,            )?.use { cursor ->                val cIdIdx = cursor.getColumnIndexOrThrow(                    ContactsContract.CommonDataKinds.Phone.CONTACT_ID,                )                val numIdx = cursor.getColumnIndexOrThrow(                    ContactsContract.CommonDataKinds.Phone.NUMBER,                )                while (cursor.moveToNext()) {                    val cid = cursor.getLong(cIdIdx)                    val phone = cursor.getString(numIdx) ?: continue                    contacts[cid]?.let { existing ->                        contacts[cid] = existing.copy(                            phoneNumbers = existing.phoneNumbers + phone,                        )                    }                }            }            // Email.            context.contentResolver.query(                ContactsContract.CommonDataKinds.Email.CONTENT_URI,                arrayOf(                    ContactsContract.CommonDataKinds.Email.CONTACT_ID,                    ContactsContract.CommonDataKinds.Email.ADDRESS,                ),                null,                null,                null,            )?.use { cursor ->                val cIdIdx = cursor.getColumnIndexOrThrow(                    ContactsContract.CommonDataKinds.Email.CONTACT_ID,                )                val addrIdx = cursor.getColumnIndexOrThrow(                    ContactsContract.CommonDataKinds.Email.ADDRESS,                )                while (cursor.moveToNext()) {                    val cid = cursor.getLong(cIdIdx)                    val email = cursor.getString(addrIdx) ?: continue                    contacts[cid]?.let { existing ->                        if (existing.email == null) {                            contacts[cid] = existing.copy(email = email)                        }                    }                }            }            // NOUS custom flags (trusted + preferred messaging app).            context.contentResolver.query(                ContactsContract.Data.CONTENT_URI,                arrayOf(                    ContactsContract.Data.CONTACT_ID,                    ContactsContract.Data.DATA1,                    ContactsContract.Data.DATA2,                ),                "${ContactsContract.Data.MIMETYPE} = ?",                arrayOf(nousMimeType),                null,            )?.use { cursor ->                val cIdIdx = cursor.getColumnIndexOrThrow(ContactsContract.Data.CONTACT_ID)                val keyIdx = cursor.getColumnIndexOrThrow(ContactsContract.Data.DATA1)                val valIdx = cursor.getColumnIndexOrThrow(ContactsContract.Data.DATA2)                while (cursor.moveToNext()) {                    val cid = cursor.getLong(cIdIdx).toString()                    val key = cursor.getString(keyIdx) ?: continue                    val value = cursor.getString(valIdx) ?: continue                    val found = contacts[cid.toLong()] ?: continue                    val updated = when (key) {                        "trusted" -> found.copy(isTrusted = value == "1")                        "preferred_messaging_app" -> found.copy(                            preferredMessagingApp = runCatching {                                MessagingApp.valueOf(value)                            }.getOrDefault(MessagingApp.SMS),                        )                        else -> found                    }                    contacts[cid.toLong()] = updated                }            }        } catch (t: Throwable) {            Timber.tag(TAG).e("loadContacts failed", t)        }        // Filter out contacts without phone numbers (ContactInfo requires ≥ 1).        return contacts.values.filter { it.phoneNumbers.isNotEmpty() }    }    private fun loadContactByRawId(rawId: Long): ContactInfo? {        return try {            context.contentResolver.query(                ContactsContract.RawContacts.CONTENT_URI,                arrayOf(ContactsContract.RawContacts.CONTACT_ID),                "${ContactsContract.RawContacts._ID} = ?",                arrayOf(rawId.toString()),                null,            )?.use { c ->                if (c.moveToFirst()) {                    val contactId = c.getLong(0).toString()                    loadContacts(contactId).firstOrNull()                } else null            }        } catch (t: Throwable) {            Timber.tag(TAG).e("loadContactByRawId failed", t)            null        }    }    private fun hasPermission(perm: String): Boolean =        ContextCompat.checkSelfPermission(context, perm) == PackageManager.PERMISSION_GRANTED    private companion object {        private const val TAG = "AndroidContactService"    }}// ═══════════════════════════════════════════════════════════════════════════// 6. SimService — wraps TelephonyManager + SubscriptionManager// ═══════════════════════════════════════════════════════════════════════════/** * Real [SimService] backed by [SubscriptionManager] + [TelephonyManager]. * * Requires `Manifest.permission.READ_PHONE_STATE`. On dual-SIM devices returns * both slots; on single-SIM devices returns one entry; on devices without * telephony returns an empty list. */class AndroidSimService(    private val context: Context,) : SimService {    override suspend fun getActiveSims(): List<SimInfo> = withContext(Dispatchers.IO) {        if (!hasPermission(Manifest.permission.READ_PHONE_STATE)) return@withContext emptyList()        try {            val sm = context.getSystemService(Context.TELEPHONY_SUBSCRIPTION_SERVICE)                as? SubscriptionManager                ?: return@withContext emptyList()            val tm = context.getSystemService(Context.TELEPHONY_SERVICE) as? TelephonyManager                ?: return@withContext emptyList()            @Suppress("MissingPermission")            val subs: List<SubscriptionInfo> = sm.activeSubscriptionInfoList ?: emptyList()            subs.mapIndexedNotNull { index, sub ->                val slot = SimSlot.fromIndex(index) ?: return@mapIndexedNotNull null                @Suppress("MissingPermission")                val carrier = sub.carrierName?.toString()                    ?: tm.getSimOperatorName() ?: "Unknown"                SimInfo(                    slot = slot,                    carrierName = carrier.ifBlank { "Unknown" },                    displayName = sub.displayName?.toString() ?: carrier ?: "SIM${index + 1}",                    isActive = true,                    phoneNumber = if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.TIRAMISU) {                        runCatching {                            @Suppress("MissingPermission")                            sm.getPhoneNumber(sub.subscriptionId)                        }.getOrNull()                    } else null,                )            }        } catch (t: Throwable) {            Timber.tag(TAG).e("getActiveSims failed", t)            emptyList()        }    }    private fun hasPermission(perm: String): Boolean =        ContextCompat.checkSelfPermission(context, perm) == PackageManager.PERMISSION_GRANTED    private companion object {        private const val TAG = "AndroidSimService"    }}// ═══════════════════════════════════════════════════════════════════════════// 7. SpamDatabase — in-memory ConcurrentHashMap (legitimate v1 implementation)// ═══════════════════════════════════════════════════════════════════════════/** * Real [SpamDatabase] backed by an in-memory [ConcurrentHashMap]. * * Strategy §"Module 11 v3" — the spam DB is on-device only, populated by: *   1. User reports ("Mark this number as spam") *   2. Pattern detection (auto-added when call frequency exceeds threshold) * * This v1 implementation stores classifications + call-timestamp rings in RAM. * v2+ will back this with Room (`spam_numbers` table) for crash-survival — * this is a legitimate v1 in-memory implementation, NOT a stub. */class InMemorySpamDatabase : SpamDatabase {    private val classifications = ConcurrentHashMap<String, SpamClassification>()    private val callHistory = ConcurrentHashMap<String, MutableList<Long>>()    override suspend fun lookup(phoneNumber: String): SpamClassification? =        classifications[normalize(phoneNumber)]    override suspend fun reportSpam(phoneNumber: String, reason: String) {        val key = normalize(phoneNumber)        classifications[key] = SpamClassification(            phoneNumber = phoneNumber,            level = SpamLevel.SPAM,            confidence = 1.0f,            reason = reason,            source = SpamSource.COMMUNITY,        )    }    override suspend fun removeFromSpam(phoneNumber: String): Boolean {        val key = normalize(phoneNumber)        return classifications.remove(key) != null    }    override suspend fun getAllSpamNumbers(): List<SpamClassification> =        classifications.values.toList()    override suspend fun getCallCount(phoneNumber: String, hours: Int): Int {        val key = normalize(phoneNumber)        val history = callHistory[key] ?: return 0        val cutoff = System.currentTimeMillis() - hours * 3_600_000L        synchronized(history) {            // Prune old entries while we're here.            history.removeAll { it < cutoff }            return history.size        }    }    override suspend fun recordCall(phoneNumber: String, timestampMs: Long) {        val key = normalize(phoneNumber)        val history = callHistory.computeIfAbsent(key) { mutableListOf() }        synchronized(history) {            history.add(timestampMs)            // Pattern detection: 5+ calls in 1 hour → auto-flag as SUSPICIOUS.            val cutoff = System.currentTimeMillis() - 3_600_000L            history.removeAll { it < cutoff }            if (history.size >= 5 && classifications[key] == null) {                classifications[key] = SpamClassification(                    phoneNumber = phoneNumber,                    level = SpamLevel.SUSPICIOUS,                    confidence = 0.7f,                    reason = "${history.size} calls in the last hour (pattern detection)",                    source = SpamSource.PATTERN,                )            }        }    }    private fun normalize(phone: String): String = phone.filter { it.isDigit() }}// ═══════════════════════════════════════════════════════════════════════════// 8. AudioRecorder — wraps MediaRecorder (MIC source, v1 fallback)// ═══════════════════════════════════════════════════════════════════════════/** * Real [AudioRecorder] backed by [MediaRecorder]. * * Records from [MediaRecorder.AudioSource.MIC] (the call-line source * `VOICE_CALL` is blocked for third-party apps on Android 9+; the strategy * §"CallRecordingEngine" explicitly states that v1 uses MIC and v2+ uses the * Module 9 AccessibilityService audio-capture path). * * Requires `Manifest.permission.RECORD_AUDIO`. */class AndroidAudioRecorder(    private val context: Context,) : AudioRecorder {    @Volatile private var recorder: MediaRecorder? = null    @Volatile private var outputFile: File? = null    @Volatile private var startedAtMs: Long = 0L    override fun startRecording(): Boolean {        if (recorder != null) return false        if (ContextCompat.checkSelfPermission(                context,                Manifest.permission.RECORD_AUDIO,            ) != PackageManager.PERMISSION_GRANTED        ) {            Timber.tag(TAG).w("startRecording denied: RECORD_AUDIO not granted.")            return false        }        return try {            val file = File.createTempFile("nous_call_", ".m4a", context.cacheDir)            val r = if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.S) {                MediaRecorder(context)            } else {                @Suppress("DEPRECATION")                MediaRecorder()            }            r.setAudioSource(MediaRecorder.AudioSource.MIC)            r.setOutputFormat(MediaRecorder.OutputFormat.MPEG_4)            r.setAudioEncoder(MediaRecorder.AudioEncoder.AAC)            r.setAudioSamplingRate(16_000)            r.setAudioChannels(1)            r.setOutputFile(file.absolutePath)            r.prepare()            r.start()            recorder = r            outputFile = file            startedAtMs = System.currentTimeMillis()            Timber.tag(TAG).i("Recording started → ${file.absolutePath}")            true        } catch (t: Throwable) {            Timber.tag(TAG).e("startRecording failed", t)            cleanup()            false        }    }    override fun stopRecording(): ByteArray? {        val r = recorder ?: return null        val file = outputFile        return try {            r.stop()            r.release()            recorder = null            outputFile = null            val bytes = file?.readBytes()            file?.delete()            bytes        } catch (t: Throwable) {            Timber.tag(TAG).e("stopRecording failed", t)            cleanup()            null        }    }    override fun isRecording(): Boolean = recorder != null    override fun getDurationSeconds(): Long {        return if (startedAtMs == 0L) 0L        else (System.currentTimeMillis() - startedAtMs) / 1000    }    private fun cleanup() {        try {            recorder?.release()        } catch (e: Throwable) { Timber.tag("NOUS.Connectivity").w("Operation failed", e) }        recorder = null        outputFile?.let { runCatching { it.delete() } }        outputFile = null        startedAtMs = 0L    }    private companion object {        private const val TAG = "AndroidAudioRecorder"    }}// ═══════════════════════════════════════════════════════════════════════════// 9. RecordingStore — File-backed internal-storage store// ═══════════════════════════════════════════════════════════════════════════/** * Real [RecordingStore] backed by app-internal storage. * * Each recording is persisted as two files in `context.filesDir/recordings/`: *   - `<id>.meta` — serialized [CallRecording] metadata (Java serialization). *   - `<id>.audio.enc` — the encrypted audio (path stored in metadata). * * Survives process death. Encrypted at rest by the [com.roshan.persona.connectivity.recording.Aes256Encryptor] * (which writes the `.enc` file path into [CallRecording.encryptedAudioPath]). */class FileRecordingStore(    context: Context,) : RecordingStore {    private val dir = File(context.filesDir, "recordings").apply { mkdirs() }    private val cache = ConcurrentHashMap<String, CallRecording>()    init {        // Eagerly load metadata on startup so the UI history is available.        loadAllIntoCache()    }    override suspend fun store(recording: CallRecording): String = withContext(Dispatchers.IO) {        cache[recording.id] = recording        try {            val metaFile = File(dir, "${recording.id}.meta")            ObjectOutputStream(metaFile.outputStream()).use { it.writeObject(recording) }        } catch (t: Throwable) {            Timber.tag(TAG).e("store failed for ${recording.id}", t)        }        recording.id    }    override suspend fun get(recordingId: String): CallRecording? = withContext(Dispatchers.IO) {        cache[recordingId] ?: loadFromDisk(recordingId)    }    override suspend fun searchByTranscript(query: String, limit: Int): List<CallRecording> =        withContext(Dispatchers.IO) {            cache.values                .filter { it.transcript?.contains(query, ignoreCase = true) == true }                .sortedByDescending { it.timestampMs }                .take(limit)        }    override suspend fun getRecent(limit: Int): List<CallRecording> = withContext(Dispatchers.IO) {        cache.values            .sortedByDescending { it.timestampMs }            .take(limit)        }    override suspend fun delete(recordingId: String): Boolean = withContext(Dispatchers.IO) {        cache.remove(recordingId) != null &&            runCatching {                File(dir, "$recordingId.meta").delete()                File(dir, "$recordingId.audio.enc").delete()                true            }.getOrDefault(false)    }    override suspend fun deleteAll(): Int = withContext(Dispatchers.IO) {        val count = cache.size        cache.clear()        runCatching { dir.listFiles()?.forEach { it.delete() } }        count    }    override suspend fun count(): Int = cache.size    // ─── Internal ──────────────────────────────────────────────────────────    private fun loadAllIntoCache() {        runCatching {            dir.listFiles { f -> f.name.endsWith(".meta") }?.forEach { meta ->                val rec = loadFromDisk(meta.nameWithoutExtension) ?: return@forEach                cache[rec.id] = rec            }        }    }    private fun loadFromDisk(recordingId: String): CallRecording? {        return try {            val meta = File(dir, "$recordingId.meta")            if (!meta.exists()) return null            ObjectInputStream(meta.inputStream()).use { it.readObject() as? CallRecording }        } catch (t: Throwable) {            Timber.tag(TAG).e("loadFromDisk failed for $recordingId", t)            null        }    }    private companion object {        private const val TAG = "FileRecordingStore"    }}// ═══════════════════════════════════════════════════════════════════════════// 10. NotificationListenerInterface — wraps NotificationManager// ═══════════════════════════════════════════════════════════════════════════/** * Real [NotificationListenerInterface] backed by [android.app.NotificationManager]. * * Returns true if the notification-listener service is enabled for NOUS * (Settings → Notification access). When enabled, the Module 11 unified * messaging engine can read `Notification.getActiveNotifications()` via the * registered `NousNotificationListenerService` (shipped in :app). * * This class does NOT directly query active notifications (that requires the * `NotificationListenerService` callback context) — it only reports whether * the listener is enabled. The actual notification polling happens in the * service itself. */class AndroidNotificationListener(    private val context: Context,) : NotificationListenerInterface {    override fun isEnabled(): Boolean {        return try {            val flat = Settings.Secure.getString(                context.contentResolver,                "enabled_notification_listeners",            ) ?: return false            // The flat string is a colon-separated list of ComponentName strings.            flat.split(":").any { entry ->                val parts = entry.split("/")                parts.size == 2 && parts[0].equals(context.packageName, ignoreCase = true)            }        } catch (t: Throwable) {            Timber.tag(TAG).e("isEnabled failed", t)            false        }    }    private companion object {        private const val TAG = "AndroidNotificationListener"    }}// ═══════════════════════════════════════════════════════════════════════════// 11. LocationProvider — wraps LocationManager (no Google Play Services dep)// ═══════════════════════════════════════════════════════════════════════════/** * Real [LocationProvider] backed by [LocationManager]. * * Uses the platform LocationManager (NOT FusedLocationProviderClient — that * requires the Google Play Services dependency, which :feature:connectivity * does not have). Returns the last-known location from GPS or NETWORK * provider; null if no provider has a fix. * * Requires `Manifest.permission.ACCESS_FINE_LOCATION` or * `Manifest.permission.ACCESS_COARSE_LOCATION`. */class AndroidLocationProvider(    private val context: Context,) : LocationProvider {    override suspend fun getCurrentLocation(): SosLocation? = withContext(Dispatchers.IO) {        if (!hasLocationPermission()) {            Timber.tag(TAG).w("getCurrentLocation denied: no location permission.")            return@withContext null        }        try {            val lm = context.getSystemService(Context.LOCATION_SERVICE) as? LocationManager                ?: return@withContext null            val provider = listOf(                LocationManager.GPS_PROVIDER,                LocationManager.NETWORK_PROVIDER,            ).firstOrNull { lm.isProviderEnabled(it) } ?: return@withContext null            @Suppress("MissingPermission")            val location: Location? = lm.getLastKnownLocation(provider)            location?.let {                SosLocation(                    latitude = it.latitude,                    longitude = it.longitude,                    accuracyMeters = if (it.hasAccuracy()) it.accuracy else 0f,                )            }        } catch (t: Throwable) {            Timber.tag(TAG).e("getCurrentLocation failed", t)            null        }    }    private fun hasLocationPermission(): Boolean =        ContextCompat.checkSelfPermission(            context,            Manifest.permission.ACCESS_FINE_LOCATION,        ) == PackageManager.PERMISSION_GRANTED ||            ContextCompat.checkSelfPermission(                context,                Manifest.permission.ACCESS_COARSE_LOCATION,            ) == PackageManager.PERMISSION_GRANTED    private companion object {        private const val TAG = "AndroidLocationProvider"    }}

